import math

class Solution:

	def binpow(self, a, b, n):
		ans = 1
		while b:
			if b & 1:
				ans = ans * a % n
			a = a * a % n
			b >>= 1
		return ans

	def isCarmichael(self, n):
		for b in range(1, n + 1):
			if math.gcd(b, n) == 1 and self.binpow(b, n - 1, n) != 1:
				return 0
		return 1
